(() => {
'use strict';
// >>> art
const ART = {
  'flipper-minus': 'data:image/webp;base64,',
  'flipper-plus': 'data:image/webp;base64,',
  'stepper-housing-off': 'data:image/webp;base64,',
  'stepper-housing-on': 'data:image/webp;base64,',
};
// <<< art
const K = window.PinballKit;
const { clamp, Spring } = K;

// Logical scene coordinates (matching the 1200 x 896 housing plate at scale 1, centered at x = 1400).
const HSIZE = [1200, 896];
const HX = 800, HY = 0;                                   // housing plate origin in scene space
const WIN = [HX + 168, HY + 432, HX + 1029, HY + 732];    // inner window aperture [x0, y0, x1, y1]
const LAMP = [HX + 600, HY + 213, 134];                   // top Fresnel lens centre and radius

// Flipper plates (measured on flipper-minus.webp and flipper-plus.webp)
const FM_SIZE = [1292, 513], FM_PIV = [250.5, 254.4];
const FP_SIZE = [1293, 514], FP_PIV = [1039.4, 254.0];
const FSCALE = 0.56;
const PL = [240, 560], PR = [2560, 560];                  // left (-) and right (+) pivot axle centres in scene space
const ANG_REST = 0.40, ANG_UP = -0.44;                    // radians: +0.40 (~23 deg down) at rest, -0.44 (~25 deg up) fired

// Overall control bounding box (without drop shadow / glow padding): this defines the element's layout box
const BOX = [106, 35, 2588, 850];
const PADX = 220, PADY = 260;
const SCALE = [-5, -3, -1, 2, 4, 7, 9, 11, 14, 16];       // shared pentatonic chime scale

// Build a crisp power-of-two (256 x 2048) vintage aged-paper score-reel digit strip (0..9) on an offscreen canvas.
// Custom condensed vintage score-reel vector glyphs ensure consistent vintage typography on every OS.
function makeStripCanvas() {
  const W = 256, H = 2048, CELL = H / 10;
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const ctx = c.getContext('2d');

  // deterministic PRNG for vintage parchment grain & specks
  let seed = 19670415;
  const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };

  // warm aged ivory parchment base with subtle edge yellowing
  const bg = ctx.createLinearGradient(0, 0, W, 0);
  bg.addColorStop(0.0, '#bca57b');
  bg.addColorStop(0.07, '#d6c39c');
  bg.addColorStop(0.22, '#e2d3b2');
  bg.addColorStop(0.5, '#e7d9ba');
  bg.addColorStop(0.78, '#e1d2b0');
  bg.addColorStop(0.93, '#d4c099');
  bg.addColorStop(1.0, '#b9a176');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // subtle vertical roller wear bands & fibrous grain
  for (let i = 0; i < 65; i++) {
    const x = rnd() * W, w = 1 + rnd() * 6;
    ctx.fillStyle = rnd() > 0.5 ? `rgba(110,82,42,${(0.015 + rnd() * 0.035).toFixed(3)})` : `rgba(255,248,232,${(0.015 + rnd() * 0.03).toFixed(3)})`;
    ctx.fillRect(x, 0, w, H);
  }
  for (let i = 0; i < 420; i++) {
    ctx.fillStyle = `rgba(92,68,36,${(0.02 + rnd() * 0.06).toFixed(3)})`;
    ctx.fillRect(rnd() * W, rnd() * H, 1 + rnd() * 3, 1 + rnd() * 8);
  }
  // faint horizontal age lines and subtle edge rivets/grooves
  for (let i = 0; i < 10; i++) {
    const y = i * CELL;
    ctx.fillStyle = 'rgba(85,62,32,0.14)';
    ctx.fillRect(0, y, W, 1.5);
  }
  ctx.fillStyle = 'rgba(65,45,22,0.18)';
  ctx.fillRect(0, 0, 7, H);
  ctx.fillRect(W - 7, 0, 7, H);

  // Draw authentic 1960s condensed electromechanical score-reel numerals 0-9
  const drawDigit = (d, cy) => {
    ctx.save();
    ctx.translate(W * 0.5, cy);
    ctx.scale(1.04, 1.07);
    // normalized coordinates: x in [-46, 46], y in [-68, 68]
    const sw = 24;
    ctx.strokeStyle = '#191613';
    ctx.fillStyle = '#191613';
    ctx.lineWidth = sw;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // slight soft ink halo underneath to mimic vintage rubber-stamped ink on paper
    const strokeDigit = (fn) => {
      ctx.save();
      ctx.strokeStyle = 'rgba(28,22,16,0.28)';
      ctx.lineWidth = sw + 3.2;
      ctx.beginPath(); fn(); ctx.stroke();
      ctx.restore();
      ctx.beginPath(); fn(); ctx.stroke();
    };

    const rrect = (x, y, w, h, r) => {
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + r);
      ctx.lineTo(x + w, y + h - r);
      ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
      ctx.lineTo(x + r, y + h);
      ctx.quadraticCurveTo(x, y + h, x, y + h - r);
      ctx.lineTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.closePath();
    };

    switch (d) {
      case 0:
        strokeDigit(() => rrect(-36, -64, 72, 128, 34));
        break;
      case 1:
        strokeDigit(() => {
          ctx.moveTo(-22, -45); ctx.lineTo(4, -64); ctx.lineTo(4, 64);
          ctx.moveTo(-26, 64); ctx.lineTo(32, 64);
        });
        break;
      case 2:
        strokeDigit(() => {
          ctx.moveTo(-34, -36);
          ctx.bezierCurveTo(-34, -72, 36, -72, 36, -34);
          ctx.bezierCurveTo(36, -6, -24, 30, -36, 64);
          ctx.lineTo(38, 64);
        });
        break;
      case 3:
        strokeDigit(() => {
          ctx.moveTo(-32, -42);
          ctx.bezierCurveTo(-24, -70, 35, -70, 35, -34);
          ctx.bezierCurveTo(35, -8, 12, -2, -8, -2);
          ctx.moveTo(-4, -2);
          ctx.bezierCurveTo(22, -2, 38, 8, 38, 34);
          ctx.bezierCurveTo(38, 70, -24, 72, -35, 42);
        });
        break;
      case 4:
        strokeDigit(() => {
          ctx.moveTo(18, 64); ctx.lineTo(18, -64);
          ctx.lineTo(-40, 22); ctx.lineTo(40, 22);
        });
        break;
      case 5:
        strokeDigit(() => {
          ctx.moveTo(33, -64); ctx.lineTo(-30, -64); ctx.lineTo(-34, -8);
          ctx.bezierCurveTo(-18, -22, 38, -20, 38, 24);
          ctx.bezierCurveTo(38, 70, -22, 72, -36, 44);
        });
        break;
      case 6:
        strokeDigit(() => {
          ctx.moveTo(30, -48);
          ctx.bezierCurveTo(18, -72, -36, -68, -36, -4);
          ctx.lineTo(-36, 28);
          ctx.bezierCurveTo(-36, 70, 36, 70, 36, 26);
          ctx.bezierCurveTo(36, -14, -32, -16, -36, 18);
        });
        break;
      case 7:
        strokeDigit(() => {
          ctx.moveTo(-36, -64); ctx.lineTo(37, -64); ctx.lineTo(-10, 64);
        });
        break;
      case 8:
        strokeDigit(() => {
          rrect(-33, -64, 66, 60, 28);
          rrect(-36, -4, 72, 68, 32);
        });
        break;
      case 9:
        strokeDigit(() => {
          ctx.moveTo(-30, 48);
          ctx.bezierCurveTo(-18, 72, 36, 68, 36, 4);
          ctx.lineTo(36, -28);
          ctx.bezierCurveTo(36, -70, -36, -70, -36, -26);
          ctx.bezierCurveTo(-36, 14, 32, 16, 36, -18);
        });
        break;
    }

    // subtle ink wear speckles over the glyph
    ctx.globalCompositeOperation = 'source-atop';
    for (let k = 0; k < 22; k++) {
      ctx.fillStyle = `rgba(222,206,174,${(0.06 + rnd() * 0.12).toFixed(3)})`;
      ctx.fillRect(-46 + rnd() * 92, -70 + rnd() * 140, 1 + rnd() * 3, 1 + rnd() * 2);
    }
    ctx.restore();
  };

  for (let d = 0; d < 10; d++) drawDigit(d, (d + 0.5) * CELL);
  return c;
}

function makeStripTexture() {
  const g = K.getGL(); if (!g) return null;
  const c = makeStripCanvas();
  const t = g.createTexture();
  g.bindTexture(g.TEXTURE_2D, t);
  g.pixelStorei(g.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
  g.texImage2D(g.TEXTURE_2D, 0, g.RGBA, g.RGBA, g.UNSIGNED_BYTE, c);
  g.generateMipmap(g.TEXTURE_2D);
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_MIN_FILTER, g.LINEAR_MIPMAP_LINEAR);
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_MAG_FILTER, g.LINEAR);
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_WRAP_S, g.CLAMP_TO_EDGE);
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_WRAP_T, g.REPEAT);
  t.ready = true;
  return t;
}

const FS = K.glsl.head + `
uniform sampler2D uOff, uOn, uFMinus, uFPlus, uStrip;
uniform float uLamp, uAngL, uAngR, uVelL, uVelR, uDigits;
uniform vec4 uDrumPos;   // continuous digit positions [d0 (leftmost), d1, d2, d3]
uniform vec4 uDrumVel;   // digit velocities for vertical motion blur
const vec3 LAMP = vec3(${LAMP[0].toFixed(1)}, ${LAMP[1].toFixed(1)}, ${LAMP[2].toFixed(1)});

vec4 over(vec4 under, vec4 top){ return top + under * (1. - top.a); }
float sdBox(vec2 p, vec2 c, vec2 h, float r){ vec2 q = abs(p - c) - h + r; return length(max(q, 0.)) + min(max(q.x, q.y), 0.) - r; }
float smin(float a, float b, float k){ float h = clamp(.5 + .5 * (b - a) / k, 0., 1.); return mix(b, a, h) - k * h * (1. - h); }

// Smooth analytical SDF of the housing bezel + top lamp lobe (for silky studio shadows with zero stepped edges)
float sdHousing(vec2 p){
  vec2 q = p - vec2(${HX.toFixed(1)}, ${HY.toFixed(1)});
  float bezel = sdBox(q, vec2(600., 590.), vec2(538., 260.), 120.);
  float lobe = length(q - vec2(600., 212.)) - 172.;
  return smin(bezel, lobe, 28.);
}

// Smooth analytical SDF of a tapered flipper bat in its rotated local frame (p.x = |perp|, p.y = along axis 0..L)
float sdUnevenCapY(vec2 p, float L, float r1, float r2){
  float b = (r1 - r2) / L;
  float a = sqrt(max(1. - b * b, 1e-4));
  float k = dot(p, vec2(-b, a));
  if (k < 0.) return length(p) - r1;
  if (k > a * L) return length(p - vec2(0., L)) - r2;
  return dot(p, vec2(a, b)) - r1;
}
float sdFlipL(vec2 p, float ang){
  vec2 d = p - vec2(${PL[0].toFixed(1)}, ${PL[1].toFixed(1)});
  float c = cos(ang), s = sin(ang);
  vec2 q = vec2(c * d.x + s * d.y, -s * d.x + c * d.y);
  return sdUnevenCapY(vec2(abs(q.y), q.x), ${(890 * FSCALE).toFixed(2)}, ${(234 * FSCALE).toFixed(2)}, ${(130 * FSCALE).toFixed(2)});
}
float sdFlipR(vec2 p, float ang){
  vec2 d = p - vec2(${PR[0].toFixed(1)}, ${PR[1].toFixed(1)});
  float c = cos(ang), s = sin(ang);
  vec2 q = vec2(c * d.x - s * d.y, s * d.x + c * d.y);
  return sdUnevenCapY(vec2(abs(q.y), -q.x), ${(890 * FSCALE).toFixed(2)}, ${(234 * FSCALE).toFixed(2)}, ${(130 * FSCALE).toFixed(2)});
}

// Sample housing plate (off / on) at scene point p — uniform texture2D (no early return!) so GPU mipmap derivatives stay clean
vec4 sampleHousing(vec2 p){
  vec2 uv = (p - vec2(${HX.toFixed(1)}, ${HY.toFixed(1)})) / vec2(${HSIZE[0].toFixed(1)}, ${HSIZE[1].toFixed(1)});
  float inside = step(.002, uv.x) * step(uv.x, .998) * step(.002, uv.y) * step(uv.y, .998);
  return mix(texture2D(uOff, uv), texture2D(uOn, uv), uLamp) * inside;
}

// Sample left (-) flipper rotated by ang (positive = tip down-right, negative = tip up-right)
vec4 sampleFlipL(vec2 p, float ang){
  vec2 d = (p - vec2(${PL[0].toFixed(1)}, ${PL[1].toFixed(1)})) / ${FSCALE.toFixed(4)};
  float c = cos(ang), s = sin(ang);
  vec2 q = vec2(c * d.x + s * d.y, -s * d.x + c * d.y) + vec2(${FM_PIV[0].toFixed(1)}, ${FM_PIV[1].toFixed(1)});
  vec2 uv = q / vec2(${FM_SIZE[0].toFixed(1)}, ${FM_SIZE[1].toFixed(1)});
  float inside = step(.002, uv.x) * step(uv.x, .998) * step(.002, uv.y) * step(uv.y, .998);
  return texture2D(uFMinus, uv) * inside;
}

// Sample right (+) flipper rotated by ang (positive = tip down-left, negative = tip up-left)
vec4 sampleFlipR(vec2 p, float ang){
  vec2 d = (p - vec2(${PR[0].toFixed(1)}, ${PR[1].toFixed(1)})) / ${FSCALE.toFixed(4)};
  float c = cos(ang), s = sin(ang);
  vec2 q = vec2(c * d.x - s * d.y, s * d.x + c * d.y) + vec2(${FP_PIV[0].toFixed(1)}, ${FP_PIV[1].toFixed(1)});
  vec2 uv = q / vec2(${FP_SIZE[0].toFixed(1)}, ${FP_SIZE[1].toFixed(1)});
  float inside = step(.002, uv.x) * step(uv.x, .998) * step(.002, uv.y) * step(uv.y, .998);
  return texture2D(uFPlus, uv) * inside;
}

// Render the recessed electromechanical score-reel drums & side ratchet gears inside the window aperture
vec4 reels(vec2 p){
  vec2 w0 = vec2(${(WIN[0] - 10).toFixed(1)}, ${(WIN[1] - 10).toFixed(1)});
  vec2 w1 = vec2(${(WIN[2] + 10).toFixed(1)}, ${(WIN[3] + 10).toFixed(1)});
  float inWin = step(w0.x, p.x) * step(p.x, w1.x) * step(w0.y, p.y) * step(p.y, w1.y);

  float wx0 = ${WIN[0].toFixed(1)}, wx1 = ${WIN[2].toFixed(1)}, ww = wx1 - wx0;
  float wy0 = ${WIN[1].toFixed(1)}, wy1 = ${WIN[3].toFixed(1)}, wh = wy1 - wy0;
  float nx = (p.x - wx0) / ww;           // 0..1 across window width
  float ny = (p.y - wy0) / wh;           // 0..1 top to bottom
  float vy = clamp(ny * 2. - 1., -1., 1.);

  // dark oiled metallic interior cavity with subtle horizontal axle shaft
  vec3 bg = vec3(.032, .028, .025);
  float shaft = 1. - smoothstep(.10, .28, abs(vy));
  float shaftLit = .35 + .65 * max(0., 1. - abs(vy + .06) * 5.5);
  bg += vec3(.22, .19, .15) * shaft * shaftLit * (.7 + .3 * vnoise(vec3(p.x * .08, p.y * .04, 2.)));

  // layout parameters for 2 or 3 drums
  float nd = uDigits;
  float margin = nd > 2.5 ? .06 : .11;
  float gap = nd > 2.5 ? .04 : .075;
  float dw = (1. - 2. * margin - (nd - 1.) * gap) / nd;
  float cell = dw + gap;
  float rel = (nx - margin) / cell;
  float idx = floor(rel);
  float fx = fract(rel) * cell;          // 0..dw is drum face, dw..cell is gap

  vec3 col = bg;
  float inDrum = step(0., idx) * step(idx, nd - .5) * step(0., fx) * step(fx, dw);

  // Pick this drum's continuous digit position and velocity
  float pos = idx < .5 ? uDrumPos.x : (idx < 1.5 ? uDrumPos.y : (idx < 2.5 ? uDrumPos.z : uDrumPos.w));
  float vel = idx < .5 ? uDrumVel.x : (idx < 1.5 ? uDrumVel.y : (idx < 2.5 ? uDrumVel.z : uDrumVel.w));

  // Brass/steel sprocket gear flanges peeking just outside each drum's left & right edges
  float gearZone = 0.;
  float gearPos = pos;
  if (inDrum < .5) {
    float nearIdx = clamp(floor(rel - .5 * dw / cell + .5), 0., nd - 1.);
    float dStart = margin + nearIdx * cell, dEnd = dStart + dw;
    float distEdge = min(abs(nx - dStart), abs(nx - dEnd));
    if (distEdge < .042 && abs(vy) < .82) {
      gearZone = 1. - smoothstep(.026, .042, distEdge);
      gearPos = nearIdx < .5 ? uDrumPos.x : (nearIdx < 1.5 ? uDrumPos.y : (nearIdx < 2.5 ? uDrumPos.z : uDrumPos.w));
    }
  }
  if (gearZone > .01) {
    float th = asin(clamp(vy * 1.15, -.98, .98));
    float tooth = .5 + .5 * sin((th / 6.2831853 * 10. + gearPos) * 18.84955);
    float gz = sqrt(max(1. - vy * vy * 1.1, .05));
    vec3 metal = mix(vec3(.24, .19, .13), vec3(.58, .48, .33), tooth * .7 + .3 * gz) * (.35 + .85 * gz);
    col = mix(col, metal, gearZone * .92);
  }

  // Cylindrical drum sampling — unconditional texture2D (no fract, relies on GL_REPEAT) for seamless mipmap LODs
  float u = clamp(fx / dw, 0., 1.);
  float cylY = clamp(vy * .94, -.985, .985);
  float theta = asin(cylY);                                 // true cylinder angle in [-pi/2, pi/2]
  float nz = cos(theta);                                    // cylinder normal z (1 at centre, 0 at edges)
  float vBase = (pos + .5 + theta * .58) / 10.;
  float blur = clamp(vel * .0024, -.024, .024);
  vec3 texCol = vec3(0.);
  for (int k = -4; k <= 4; k++) {
    float t = float(k) / 4.;
    float w = 1. - .45 * abs(t);
    texCol += texture2D(uStrip, vec2(u, vBase + blur * t)).rgb * w;
  }
  texCol /= 6.75;

  if (inDrum > .5) {
    vec3 N = normalize(vec3((u - .5) * .22, sin(theta), nz));
    vec3 L = normalize(vec3(-.25, -.38, .89));
    float diff = .28 + .80 * max(dot(N, L), 0.);
    float spec = pow(max(dot(N, normalize(L + vec3(0., 0., 1.))), 0.), 20.) * .15;
    float rimX = smoothstep(0., .09, u) * smoothstep(1., .91, u);
    float cavY = smoothstep(0., .22, ny) * smoothstep(1., .76, ny);
    col = texCol * diff * (.55 + .45 * rimX) * (.22 + .78 * cavY) + vec3(1., .96, .88) * spec * cavY;
  }

  // Recessed shadow cast by the rectangular metal bezel walls onto the interior cavity
  float wallShadow = (.35 + .65 * smoothstep(0., .08, nx)) * (.45 + .55 * smoothstep(1., .92, nx))
                   * (.25 + .75 * smoothstep(0., .16, ny)) * (.40 + .60 * smoothstep(1., .86, ny));
  col *= wallShadow;

  // Warm amber incandescent light spilling down from the top Fresnel lamp onto the upper drums!
  if (uLamp > .002) {
    float dl = length(p - LAMP.xy);
    float spill = uLamp * exp(-max(dl - 180., 0.) / 260.) * smoothstep(.95, .02, ny);
    col += lampCol(uLamp) * spill * (inDrum > .5 ? .58 : .22);
  }

  return vec4(col, 1.) * inWin;
}

void main(){
  vec2 p = uView.xy + vUv * uView.zw;

  // 1. Silky analytical SDF shadows on the page beneath housing and both flippers (contact AO + soft directional cast)
  float dH_ao = sdHousing(p - vec2(4., 8.));
  float dH_cast = sdHousing(p - vec2(18., 34.));
  float shH = max((1. - smoothstep(-10., 28., dH_ao)) * .22, (1. - smoothstep(-22., 76., dH_cast)) * .28);

  float liftL = smoothstep(${ANG_REST.toFixed(2)}, ${ANG_UP.toFixed(2)}, uAngL);
  float liftR = smoothstep(${ANG_REST.toFixed(2)}, ${ANG_UP.toFixed(2)}, uAngR);
  float dL_ao = sdFlipL(p - vec2(3., 6.), uAngL);
  float dL_cast = sdFlipL(p - vec2(15. + 9. * liftL, 26. + 12. * liftL), uAngL);
  float shL = max((1. - smoothstep(-8., 22., dL_ao)) * (.24 - .08 * liftL), (1. - smoothstep(-18., 64. + 22. * liftL, dL_cast)) * (.30 - .05 * liftL));

  float dR_ao = sdFlipR(p - vec2(3., 6.), uAngR);
  float dR_cast = sdFlipR(p - vec2(15. + 9. * liftR, 26. + 12. * liftR), uAngR);
  float shR = max((1. - smoothstep(-8., 22., dR_ao)) * (.24 - .08 * liftR), (1. - smoothstep(-18., 64. + 22. * liftR, dR_cast)) * (.30 - .05 * liftR));

  vec4 c = vec4(0., 0., 0., max(shH, max(shL, shR)));

  // 2. Score reels inside the recessed window, then the photographed steel bezel housing on top
  c = over(c, reels(p));
  vec4 h = sampleHousing(p);
  c = over(c, h);

  // 3. Left (-) and Right (+) flippers with silky 7-tap rotational shutter blur during fast solenoid snaps
  float blL = clamp(uVelL * .0075, -.075, .075);
  vec4 fL = vec4(0.);
  if (abs(blL) > .005) {
    // Trail blur slightly behind current leading edge for natural shutter smear
    for (int k = 0; k < 7; k++) {
      float f = float(k) / 6.;
      float w = mix(1.0, 0.35, f);
      fL += sampleFlipL(p, uAngL - blL * f) * w;
    }
    fL /= 4.725;
  } else {
    fL = sampleFlipL(p, uAngL);
  }
  float blR = clamp(uVelR * .0075, -.075, .075);
  vec4 fR = vec4(0.);
  if (abs(blR) > .005) {
    for (int k = 0; k < 7; k++) {
      float f = float(k) / 6.;
      float w = mix(1.0, 0.35, f);
      fR += sampleFlipR(p, uAngR - blR * f) * w;
    }
    fR /= 4.725;
  } else {
    fR = sampleFlipR(p, uAngR);
  }
  // Subtle warm amber bounce from top lamp onto the inner tips of the flippers when lit
  if (uLamp > .002) {
    float gL = uLamp * exp(-max(length(p - LAMP.xy) - 240., 0.) / 320.) * .22;
    fL.rgb += lampCol(uLamp) * gL * fL.a;
    fR.rgb += lampCol(uLamp) * gL * fR.a;
  }
  c = over(c, fL);
  c = over(c, fR);

  // 4. Camera bloom halo around the top amber Fresnel lamp when lit (fades smoothly to zero inside canvas bounds)
  if (uLamp > .002) {
    float d = max(length(p - LAMP.xy) - LAMP.z, 0.);
    float fade = smoothstep(320., 60., d);
    float halo = uLamp * uLamp * fade * (.11 * exp(-d / 100.) * c.a + .05 * exp(-d / 150.) * (1. - c.a) * edgeFade());
    c.rgb += lampCol(uLamp) * halo;
  }
  gl_FragColor = c;
}`;

let prog, tex;
function assets() {
  if (prog === undefined) {
    try { prog = K.program(K.glsl.vs, FS); } catch (e) { console.error('pinball-stepper shader:', e.message); prog = null; }
    const again = () => document.querySelectorAll('pinball-stepper').forEach((t) => { t.dirty = true; });
    tex = prog && {
      off: K.texture(ART['stepper-housing-off'], again),
      on: K.texture(ART['stepper-housing-on'], again),
      fMinus: K.texture(ART['flipper-minus'], again),
      fPlus: K.texture(ART['flipper-plus'], again),
      strip: makeStripTexture(),
    };
  }
  return prog;
}
const rgb = (css) => { const m = /^#?([0-9a-f]{6})$/i.exec(css.trim()); if (!m) return null; const n = parseInt(m[1], 16); return [(n >> 16) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; };

class PinballStepper extends K.Base {
  static observedAttributes = ['value', 'min', 'max', 'step', 'digits', 'label', 'disabled'];
  static formAssociated = true;
  formValue() { return String(this.val); }
  static css = `
    :host{display:inline-block;vertical-align:middle;height:var(--pb-size,52px);aspect-ratio:${BOX[2]}/${BOX[3]};position:relative;-webkit-tap-highlight-color:transparent;user-select:none}
    :host([disabled]){opacity:.5;pointer-events:none}
    .ctrl{position:absolute;inset:0;outline:none;border-radius:16px;touch-action:pan-y}
    .ctrl:focus-visible{outline:2px solid var(--pb-focus,#e8961e);outline-offset:4px}
    .hit{all:unset;position:absolute;top:14%;bottom:-4%;cursor:pointer}
    .hit.minus{left:0;width:34%;border-radius:999px}
    .hit.plus{right:0;width:34%;border-radius:999px}
    .hit.reels{left:34%;right:34%;top:36%;bottom:6%;cursor:ns-resize}
    canvas{position:absolute;top:${-100 * PADY / BOX[3]}%;left:${-100 * PADX / BOX[2]}%;width:${100 * (BOX[2] + 2 * PADX) / BOX[2]}%;height:${100 * (BOX[3] + 2 * PADY) / BOX[3]}%;pointer-events:none}`;
  render() {
    return '<canvas></canvas><div class="ctrl" role="spinbutton" tabindex="0" part="control">' +
      '<button class="hit minus" type="button" tabindex="-1" aria-label="Decrease"></button>' +
      '<div class="hit reels" aria-hidden="true"></div>' +
      '<button class="hit plus" type="button" tabindex="-1" aria-label="Increase"></button></div>';
  }

  num(name, d) { const v = parseFloat(this.getAttribute(name)); return Number.isFinite(v) ? v : d; }
  get min() { return this.num('min', 0); }
  get max() { return Math.max(this.num('max', 99), this.min); }
  get stepSize() { return Math.max(1, Math.round(this.num('step', 1))); }
  get digitCount() {
    const attr = parseInt(this.getAttribute('digits'), 10);
    if (Number.isFinite(attr) && attr >= 2 && attr <= 4) return attr;
    return clamp(Math.max(2, String(Math.round(Math.abs(this.max))).length), 2, 4);
  }
  get value() { return this.val; }
  set value(v) { this.put(+v, false, 0); }
  snap(v) { const a = this.min, b = this.max, st = this.stepSize; return clamp(Math.round((clamp(v, a, b) - a) / st) * st + a, a, b); }

  // Continuous unwrapped digit target for drum i (0 = ones, 1 = tens, 2 = hundreds, ...)
  drumTarget(val, place) { return Math.floor(Math.max(0, Math.round(val)) / (10 ** place)); }

  setup() {
    this.val = this.snap(this.num('value', 0));
    // flipper states: 0 = rest (angled down), 1 = upper stop (angled up)
    this.flL = 0; this.fvL = 0; this.holdL = false; this.hitTopL = false; this.hitBotL = true;
    this.flR = 0; this.fvR = 0; this.holdR = false; this.hitTopR = false; this.hitBotR = true;
    this.repSide = 0; this.repTimer = 0;
    // score-reel drums (up to 4 places: index 0 = ones, 1 = tens, ...)
    this.dPos = [0, 1, 2, 3].map((i) => this.drumTarget(this.val, i));
    this.dTo = [...this.dPos];
    this.dVel = [0, 0, 0, 0];
    this.dDelay = [0, 0, 0, 0];
    this.lamp = 0; this.lampHold = 0;
    this.bump = new Spring(0, 1400, 34);

    this.cv = this.$('canvas'); this.ctrl = this.$('.ctrl');
    this.btnM = this.$('.minus'); this.btnP = this.$('.plus'); this.reelZone = this.$('.reels');
    if (!this.hasAttribute('aria-label') && !this.hasAttribute('aria-labelledby')) this.ctrl.setAttribute('aria-label', this.getAttribute('label') || 'Stepper');
    this.aria(); this.restyle();

    // Pointer handling for both flippers (press fires immediately & holds flipper UP; long hold auto-repeats)
    const bindFlipper = (el, dir) => {
      let active = false;
      const down = (e) => {
        if (e.button) return;
        e.preventDefault();
        el.setPointerCapture(e.pointerId);
        this.ctrl.focus({ preventScroll: true });
        active = true;
        this.pressFlipper(dir, true);
      };
      const up = () => {
        if (!active) return;
        active = false;
        this.releaseFlipper(dir);
      };
      el.addEventListener('pointerdown', down);
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      // Support synthetic click (e.g. assistive tech or scripted .click())
      el.addEventListener('click', (e) => { if (e.detail === 0) this.nudge(dir, true); });
    };
    bindFlipper(this.btnM, -1);
    bindFlipper(this.btnP, 1);

    // Dragging vertically on the score reels also steps them
    let drag = null;
    this.reelZone.addEventListener('pointerdown', (e) => {
      if (e.button) return;
      this.reelZone.setPointerCapture(e.pointerId);
      this.ctrl.focus({ preventScroll: true });
      drag = { y: e.clientY, start: this.val, acc: 0 };
    });
    this.reelZone.addEventListener('pointermove', (e) => {
      if (!drag) return;
      const stepPx = Math.max(14, this.clientHeight * 0.24);
      const dy = drag.y - e.clientY;
      const steps = Math.trunc((dy - drag.acc) / stepPx);
      if (steps !== 0) {
        drag.acc += steps * stepPx;
        const dir = Math.sign(steps);
        for (let k = Math.abs(steps); k--;) this.nudge(dir, true);
      }
    });
    const endDrag = () => { if (!drag) return; const moved = drag.start !== this.val; drag = null; if (moved) this.emit('change', { value: this.val }); };
    this.reelZone.addEventListener('pointerup', endDrag);
    this.reelZone.addEventListener('pointercancel', endDrag);

    // Keyboard control on the spinbutton
    this.ctrl.addEventListener('keydown', (e) => {
      const st = this.stepSize, big = Math.max(st, Math.min(10, Math.round((this.max - this.min) / 10) || st));
      let dir = 0, next = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowUp' || e.key === '+' || e.key === '=') { dir = 1; next = this.val + st; }
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === '-' || e.key === '_') { dir = -1; next = this.val - st; }
      else if (e.key === 'PageUp') { dir = 1; next = this.val + big; }
      else if (e.key === 'PageDown') { dir = -1; next = this.val - big; }
      else if (e.key === 'Home') { dir = -1; next = this.min; }
      else if (e.key === 'End') { dir = 1; next = this.max; }
      if (next === null) return;
      e.preventDefault();
      if (!e.repeat) this.kickFlipper(dir, true);
      else this.microKick(dir);
      const was = this.val;
      this.put(next, true, dir);
      if (this.val !== was) this.emit('change', { value: this.val });
    });
    this.ctrl.addEventListener('keyup', (e) => {
      if (e.key === 'ArrowRight' || e.key === 'ArrowUp' || e.key === '+' || e.key === '=' || e.key === 'PageUp' || e.key === 'End') this.releaseFlipper(1);
      if (e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === '-' || e.key === '_' || e.key === 'PageDown' || e.key === 'Home') this.releaseFlipper(-1);
    });
    this.ctrl.addEventListener('blur', () => { this.releaseFlipper(-1); this.releaseFlipper(1); });
  }

  attributeChangedCallback(name, was, value) {
    if (!this.ready || was === value) return;
    if (name === 'value') { const nv = this.snap(+value); if (nv !== this.val) this.put(nv, false, Math.sign(nv - this.val)); }
    else if (name === 'label') this.ctrl.setAttribute('aria-label', value || 'Stepper');
    else if (name !== 'disabled') { this.put(this.val, false, 0); this.aria(); }
    this.wake();
  }
  aria() {
    this.ctrl.setAttribute('aria-valuemin', this.min);
    this.ctrl.setAttribute('aria-valuemax', this.max);
    this.ctrl.setAttribute('aria-valuenow', this.val);
  }
  restyle() { this.page = rgb(getComputedStyle(this).getPropertyValue('--pb-page')) || [0.953, 0.937, 0.898]; this.wake(); }
  wake() { this.dirty = true; K.start(); }

  increment(n = 1) { this.nudge(1, false, n); }
  decrement(n = 1) { this.nudge(-1, false, n); }

  nudge(dir, user, mult = 1) {
    this.kickFlipper(dir, false);
    const was = this.val;
    this.put(this.val + dir * this.stepSize * mult, user, dir);
    if (user && this.val !== was) this.emit('change', { value: this.val });
  }

  pressFlipper(dir, user) {
    this.kickFlipper(dir, true);
    this.repSide = dir; this.repTimer = 0.38; this.repUser = user;
    const was = this.val;
    this.put(this.val + dir * this.stepSize, user, dir);
    if (user && this.val !== was) this.emit('change', { value: this.val });
  }
  releaseFlipper(dir) {
    if (dir < 0) this.holdL = false; else this.holdR = false;
    if (this.repSide === dir) this.repSide = 0;
    this.wake();
  }
  kickFlipper(dir, hold) {
    if (dir < 0) { this.holdL = hold; this.hitTopL = false; this.hitBotL = false; this.fvL = Math.max(this.fvL, 26); }
    else { this.holdR = hold; this.hitTopR = false; this.hitBotR = false; this.fvR = Math.max(this.fvR, 26); }
    this.fx.kick(0.72);
    this.bump.v += dir * 65;
    this.wake();
  }
  microKick(dir) {
    // subtle solenoid re-pulse while holding a flipper down for auto-repeat
    if (dir < 0) { this.flL = Math.min(this.flL, 0.84); this.fvL = 16; this.hitTopL = false; }
    else { this.flR = Math.min(this.flR, 0.84); this.fvR = 16; this.hitTopR = false; }
    this.fx.kick(0.42);
    this.bump.v += dir * 32;
    this.wake();
  }

  put(v, user, dir = 0) {
    const next = this.snap(v);
    if (next === this.val) {
      // At min/max limit: physical dead-stop nudge on the reels
      if (dir !== 0 && !K.calm) { this.dVel[0] += dir * 3.8; this.fx.tock(0.55); this.bump.v += dir * 35; this.wake(); }
      return;
    }
    const prev = this.val;
    const stepDir = dir || Math.sign(next - prev);
    this.val = next;
    this.aria(); this.syncForm();
    for (let i = 0; i < 4; i++) {
      const target = this.drumTarget(next, i);
      const prevT = this.drumTarget(prev, i);
      // If jumping far (e.g. Home/End), keep at most one lively full turn on lower drums
      if (Math.abs(target - this.dPos[i]) > 12) {
        const diff = target - this.dPos[i];
        this.dPos[i] = target - Math.sign(diff) * (4 + (Math.abs(diff) % 6));
      }
      this.dTo[i] = target;
      if (K.calm) { this.dPos[i] = target; this.dVel[i] = 0; this.dDelay[i] = 0; }
      else if (target !== prevT) {
        // Mechanical carry ripple: tens drum kicks ~36ms after ones drum
        this.dDelay[i] = i * 0.036;
        if (i === 0) this.dVel[i] += stepDir * 4.5;
      }
    }
    if (dir === 0 && !K.calm) this.kickFlipper(stepDir, false);
    this.lamp = Math.max(this.lamp, 0.88);
    this.lampHold = 0.16;
    this.fx.relay(stepDir > 0, next % 10);
    this.fx.chime(SCALE[((next % SCALE.length) + SCALE.length) % SCALE.length], 0.15, 0.35);
    if (user) this.emit('input', { value: this.val });
    this.wake();
  }

  stepFlipper(h, pos, vel, hold, hitTop, hitBot) {
    if (hold) {
      // Solenoid energized: slam to upper stop (1.0) and hold firmly against rubber stop
      const w = 52, z = 0.42;
      vel += (-w * w * (pos - 1.04) - 2 * z * w * vel) * h;
      pos += vel * h;
      if (pos >= 1.0) {
        pos = 1.0;
        if (!hitTop && vel > 2.5) { hitTop = true; this.fx.clack(clamp(vel / 28, 0.25, 0.65)); }
        if (vel > 0) vel *= -0.18;
      }
    } else {
      // Impulse snap up if moving fast, else return spring pulls down to rest stop (0.0)
      if (!hitTop && vel > 4 && pos < 1.0) {
        // Still riding the solenoid kick on a quick tap
        pos += vel * h;
        vel *= Math.exp(-h * 3.5);
        if (pos >= 1.0) {
          pos = 1.0; hitTop = true;
          this.fx.clack(clamp(vel / 28, 0.28, 0.65));
          vel = -vel * 0.24 - 4.0;
        }
      } else {
        const w = 23, z = 0.46;
        vel += (-w * w * pos - 2 * z * w * vel) * h;
        pos += vel * h;
        if (pos <= 0.0) {
          pos = 0.0;
          if (!hitBot && Math.abs(vel) > 1.8) { hitBot = true; this.fx.tock(clamp(Math.abs(vel) / 14, 0.12, 0.42)); }
          if (vel < 0) vel *= -0.24;
        }
      }
    }
    return [pos, vel, hitTop, hitBot];
  }

  step(h) {
    // Auto-repeat while holding a flipper
    if (this.repSide) {
      this.repTimer -= h;
      if (this.repTimer <= 0) {
        this.repTimer = 0.13;
        const dir = this.repSide;
        this.microKick(dir);
        const was = this.val;
        this.put(this.val + dir * this.stepSize, this.repUser, dir);
        if (this.repUser && this.val !== was) this.emit('change', { value: this.val });
      }
    }

    [this.flL, this.fvL, this.hitTopL, this.hitBotL] = this.stepFlipper(h, this.flL, this.fvL, this.holdL, this.hitTopL, this.hitBotL);
    [this.flR, this.fvR, this.hitTopR, this.hitBotR] = this.stepFlipper(h, this.flR, this.fvR, this.holdR, this.hitTopR, this.hitBotR);

    // Score reel drums: crisp stepper spring with slight overshoot into mechanical detent
    for (let i = 0; i < 4; i++) {
      if (this.dDelay[i] > 0) {
        this.dDelay[i] = Math.max(0, this.dDelay[i] - h);
        if (this.dDelay[i] === 0 && Math.abs(this.dTo[i] - this.dPos[i]) > 0.01) {
          this.dVel[i] += Math.sign(this.dTo[i] - this.dPos[i]) * 3.5;
          this.fx.relay(this.dTo[i] > this.dPos[i], (this.val + i * 3) % 10);
        }
        continue;
      }
      const d = this.dPos[i] - this.dTo[i];
      const w = 22.5, z = 0.54;
      this.dVel[i] += (-w * w * d - 2 * z * w * this.dVel[i]) * h;
      this.dPos[i] += this.dVel[i] * h;
    }

    // Incandescent top Fresnel lamp flash & warm filament afterglow
    if (this.lampHold > 0) {
      this.lampHold = Math.max(0, this.lampHold - h);
      this.lamp += (1 - this.lamp) * (1 - Math.exp(-h / 0.028));
    } else {
      this.lamp *= Math.exp(-h / 0.16);
      if (this.lamp < 0.002) this.lamp = 0;
    }
  }

  frame(dt) {
    const flipBusy = this.holdL || this.holdR || this.flL > 1e-3 || Math.abs(this.fvL) > 5e-3 || this.flR > 1e-3 || Math.abs(this.fvR) > 5e-3;
    const drumBusy = this.dPos.some((p, i) => this.dDelay[i] > 0 || Math.abs(p - this.dTo[i]) > 4e-4 || Math.abs(this.dVel[i]) > 4e-3);
    const busy = flipBusy || drumBusy || this.lamp > 0.002 || this.lampHold > 0 || !this.bump.idle;
    if (busy && dt > 0) {
      for (let n = Math.ceil(dt / 0.004), h = dt / n; n--;) this.step(h);
      this.bump.step(dt);
    } else if (!busy) {
      this.flL = this.fvL = this.flR = this.fvR = 0;
      for (let i = 0; i < 4; i++) { this.dPos[i] = this.dTo[i]; this.dVel[i] = 0; }
    }
    if (busy || this.dirty) this.draw();
    this.dirty = false;
    return busy;
  }

  draw() {
    const p = assets();
    if (!p || !tex.off.ready || !tex.on.ready || !tex.fMinus.ready || !tex.fPlus.ready || !tex.strip.ready || !this.cv.clientWidth) return;
    const dpr = Math.min(3, window.devicePixelRatio || 1);
    const w = Math.max(1, Math.round(this.cv.clientWidth * dpr));
    const h = Math.max(1, Math.round(this.cv.clientHeight * dpr));
    if (this.cv.width !== w || this.cv.height !== h) { this.cv.width = w; this.cv.height = h; }
    const vw = BOX[2] + 2 * PADX, vh = BOX[3] + 2 * PADY;
    const nd = this.digitCount;
    // Pack leftmost-to-rightmost drums into vec4 uDrumPos / uDrumVel
    const dp = [0, 0, 0, 0], dv = [0, 0, 0, 0];
    for (let i = 0; i < nd; i++) {
      const place = nd - 1 - i;
      dp[i] = this.dPos[place];
      dv[i] = this.dVel[place];
    }
    const angL = K.lerp(ANG_REST, ANG_UP, this.flL);
    const angR = K.lerp(ANG_REST, ANG_UP, this.flR);
    const velL = (ANG_UP - ANG_REST) * this.fvL;
    const velR = (ANG_UP - ANG_REST) * this.fvR;

    K.paint(p, w, h, (g, u) => {
      g.uniform4f(u.uView, BOX[0] - PADX - this.bump.x, BOX[1] - PADY, vw, vh);
      g.uniform1f(u.uPx, vw / w);
      g.uniform3f(u.uPage, ...this.page);
      g.uniform1f(u.uLamp, clamp(this.lamp));
      g.uniform1f(u.uAngL, angL); g.uniform1f(u.uAngR, angR);
      g.uniform1f(u.uVelL, velL); g.uniform1f(u.uVelR, velR);
      g.uniform1f(u.uDigits, nd);
      g.uniform4f(u.uDrumPos, dp[0], dp[1], dp[2], dp[3]);
      g.uniform4f(u.uDrumVel, dv[0], dv[1], dv[2], dv[3]);
      [tex.off, tex.on, tex.fMinus, tex.fPlus, tex.strip].forEach((t, i) => {
        g.activeTexture(g.TEXTURE0 + i); g.bindTexture(g.TEXTURE_2D, t);
      });
      g.uniform1i(u.uOff, 0); g.uniform1i(u.uOn, 1); g.uniform1i(u.uFMinus, 2); g.uniform1i(u.uFPlus, 3); g.uniform1i(u.uStrip, 4);
    }, this.cv);
  }
}
K.define('pinball-stepper', PinballStepper);
})();
